# Old categories were language/framework/data/tool; new ones are capability areas (D-031).
FRONTEND_NAMES = {"HTML", "CSS", "JavaScript", "Bootstrap 5"}
MOBILE_NAMES = {"Flutter", "Dart"}
OLD_FALLBACK = {"language": "backend", "framework": "backend", "data": "database", "tool": "tool"}
NEW_TO_OLD = {
    "backend": "framework",
    "frontend": "framework",
    "mobile": "framework",
    "database": "data",
    "tool": "tool",
}


def to_capability_areas(apps, schema_editor):
    Skill = apps.get_model("profiles", "Skill")
    for skill in Skill.objects.all():
        if skill.name in FRONTEND_NAMES:
            skill.category = "frontend"
        elif skill.name in MOBILE_NAMES:
            skill.category = "mobile"
        else:
            skill.category = OLD_FALLBACK.get(skill.category, skill.category)
        skill.save(update_fields=["category"])


def to_old_categories(apps, schema_editor):
    Skill = apps.get_model("profiles", "Skill")
    for skill in Skill.objects.all():
        skill.category = NEW_TO_OLD.get(skill.category, skill.category)
        skill.save(update_fields=["category"])


